int opeu_new_game_setup(PARAMETERS) {
  BUFFER_LOCAL;
  int16_t handle;
  uint8_t selection, scenario;
  int     new_game;

  opeu_load_message_graphics();
  handle = opeu_open_resource(opeu_scensel_file);
restart:
  opeu_set_turn_context(0);
  opeu_music_stop();
  opeu_set_turn_context(7);
  opeu_finish_side_initialization(1);
title:
  opeu_vga_clear();
  opeu_picture_file_masked(0, 0, handle, 0);
  opeu_palette_title_screen();
  opeu_ui_text(opeu_scensel_colors);
  opeu_army_position(4, 0xf4);
  selection = opeu_prompt_value_required(opeu_scensel_start_prompt, 2,
                                         opeu_scensel_start_menu);
  if (selection == 1) {
    new_game = 1;
scenario_menu:
    opeu_scenario_clear_panel();
    opeu_army_position(4, 0x12c);
    selection = opeu_prompt_value_cancel(opeu_scensel_scenario_prompt, 6,
                                         opeu_scensel_scenario_menu);
    if (selection == 0xff)
      goto title;
    scenario = selection;
    opeu_load_scenario_text(scenario, buf);
    opeu_picture_file_masked(0x15c, 0x10, handle,
                             opeu_scensel_pictures[scenario]);
    opeu_army_position(4, 0x18);
    opeu_scenario_clear_panel();
    opeu_scenario_description(buf);
    opeu_setup_marker_show(scenario);
    if (!opeu_ask_yes_no(opeu_scensel_empty))
      goto rejected;
    opeu_load_scenario(scenario);
    opeu_set_turn_context(0);
    opeu_music_stop();
    opeu_set_turn_context((uint8_t)(opeu_scenario + 1));
players:
    opeu_scenario_clear_panel();
    opeu_scenario_frame();
    opeu_scenario_clear_text();
    opeu_army_position(6, 7);
    switch (opeu_scenario + 1) {
      case 1:  opeu_army_print(opeu_scensel_france); break;
      case 2:  opeu_army_print(opeu_scensel_africa); break;
      case 3:  opeu_army_print(opeu_scensel_kursk); break;
      case 4:  opeu_army_print(opeu_scensel_dday); break;
      case 5:  opeu_army_print(opeu_scensel_bulge); break;
      default: opeu_army_print(opeu_scensel_berlin); break;
    }
    opeu_army_position(4, 0xf4);
    selection = opeu_prompt_value_cancel(opeu_scensel_players_prompt, 3,
                                         opeu_scensel_players_menu);
    if (selection == 0xff) {
      opeu_set_turn_context(0);
      opeu_music_stop();
      opeu_set_turn_context(7);
      opeu_finish_side_initialization(1);
rejected:
      opeu_setup_marker_hide(scenario);
      goto scenario_menu;
    }
    switch (selection) {
      case 1:
        opeu_army_position(4, 0x19);
        opeu_scenario_message(opeu_scensel_demo);
        opeu_side_control[1] = opeu_side_control[0] = 0;
view_side:
        opeu_scenario_clear_text();
        opeu_army_position(4, 0xdc);
        selection = opeu_prompt_value_cancel(opeu_scensel_view_prompt, 2,
                                             opeu_scensel_side_menu);
        if (selection == 0xff)
          goto players;
        if (!opeu_input_mode)
          selection = selection == 1 ? 2 : 1;
        if (selection == 1) {
          SIDE_STATUS[0] = 1;
          SIDE_STATUS[1] = 0;
        } else {
          SIDE_STATUS[0] = 0;
          SIDE_STATUS[1] = 1;
        }
        opeu_request_format(buf, opeu_scensel_view_format,
                            opeu_side_names[selection - 1]);
        opeu_army_position(4, 0x28);
        opeu_army_print(opeu_scensel_view_line, buf);
        opeu_message_delay = 7;
        break;
      case 2:
        opeu_army_position(4, 0x19);
        opeu_army_print(opeu_scensel_one_player, buf);
command_side:
        opeu_scenario_clear_text();
        opeu_army_position(4, 0xdc);
        selection = opeu_prompt_value_cancel(opeu_scensel_command_prompt, 2,
                                             opeu_scensel_side_menu);
        if (selection == 0xff)
          goto players;
        if (!opeu_input_mode)
          selection--;
        if (selection == 1) {
          SIDE_STATUS[0] = opeu_side_control[0] = 1;
          SIDE_STATUS[1] = opeu_side_control[1] = 0;
        } else {
          selection      = 2;
          SIDE_STATUS[0] = opeu_side_control[0] = 0;
          SIDE_STATUS[1] = opeu_side_control[1] = 1;
        }
        opeu_request_format(buf, opeu_scensel_command_format,
                            opeu_side_names[selection - 1]);
        opeu_army_position(4, 0x28);
        opeu_army_print(opeu_scensel_command_line, buf);
        break;
      case 3:
        opeu_army_position(4, 0x19);
        opeu_army_print(opeu_scensel_two_players, buf);
        SIDE_STATUS[1] = SIDE_STATUS[0] = opeu_side_control[1] =
            opeu_side_control[0]        = 1;
        break;
      default: goto title;
    }
map:
    opeu_scenario_clear_text();
    opeu_army_position(4, 0xdc);
    opeu_map_mode = opeu_prompt_value_cancel(opeu_scensel_map_prompt, 2,
                                             opeu_scensel_map_menu);
    if (opeu_map_mode == 0xff) {
      if (opeu_side_control[0] == 1 && opeu_side_control[1] == 1)
        goto players;
      if (opeu_side_control[0] == 0 && opeu_side_control[1] == 0)
        goto view_side;
      goto command_side;
    }
    opeu_map_mode--;
    if (!opeu_input_mode) {
      if (!opeu_map_mode)
        opeu_map_mode = 1;
      else
        opeu_map_mode = 0;
    }
    opeu_request_format(buf, opeu_scensel_map_format,
                        !opeu_map_mode ? opeu_scensel_aerial
                                       : opeu_scensel_field);
    opeu_army_position(4, 0x37);
    opeu_army_print(opeu_scensel_map_line, buf);
battles:
    opeu_scenario_clear_text();
    if (opeu_side_control[0] == 0 && opeu_side_control[1] == 0) {
      opeu_army_position(4, 0xdc);
      selection = opeu_prompt_value_cancel(opeu_scensel_battles_prompt, 2,
                                           opeu_scensel_battles_menu);
    } else {
      opeu_army_position(4, 0xf4);
      selection = opeu_prompt_value_cancel(opeu_scensel_battles_prompt2, 3,
                                           opeu_scensel_battles_menu2);
    }
    if (selection == 0xff)
      goto map;
    switch (selection) {
      case 1:
        opeu_battle_view = 1;
        opeu_string_copy(buf, opeu_scensel_view_all);
        break;
      case 2:
        opeu_battle_view = 0;
        opeu_string_copy(buf, opeu_scensel_view_none);
        break;
      default:
        opeu_battle_view = 0xff;
        opeu_string_copy(buf, opeu_scensel_view_selected);
        break;
    }
    opeu_army_position(4, 0x46);
    opeu_army_print(opeu_scensel_battles_line, buf);
difficulty:
    if ((opeu_side_control[0] == 1 && opeu_side_control[1] == 0) ||
        (opeu_side_control[0] == 0 && opeu_side_control[1] == 1)) {
      opeu_scenario_clear_text();
      opeu_army_position(4, 0x124);
      opeu_delivery_level = opeu_prompt_value_cancel(
          opeu_scensel_difficulty_prompt, 5, opeu_scensel_difficulty_menu);
      if (opeu_delivery_level == 0xff)
        goto battles;
      opeu_delivery_level--;
      opeu_string_copy(buf, opeu_scensel_difficulty);
      switch (opeu_delivery_level) {
        case 0: opeu_string_append(buf, opeu_scensel_very_easy); break;
        case 1: opeu_string_append(buf, opeu_scensel_easy); break;
        case 2: opeu_string_append(buf, opeu_scensel_average); break;
        case 3: opeu_string_append(buf, opeu_scensel_hard); break;
        case 4: opeu_string_append(buf, opeu_scensel_very_hard); break;
      }
      opeu_army_position(4, 0x55);
      opeu_army_print(opeu_scensel_difficulty_line, buf);
    }
    opeu_ui_box(4, 0x86, 0x22, 0xe0, 7);
    opeu_army_position(4, 0x154);
    if (!opeu_ask_yes_no(opeu_scensel_settings_ok)) {
      opeu_army_position(4, 0x154);
      opeu_army_print(opeu_scensel_reselect);
      opeu_ui_box(4, 0x86, 0x22, 0xe0, 7);
      if ((opeu_side_control[0] == 1 && opeu_side_control[1] == 0) ||
          (opeu_side_control[0] == 0 && opeu_side_control[1] == 1))
        goto difficulty;
      goto battles;
    }
    if (opeu_side_control[0] == 0 && opeu_side_control[1] == 0) {
      opeu_confirm_generals();
      opeu_ui_box(2, 0x86, 0x22, 0x154, 7);
      opeu_army_position(4, 0x154);
      if (opeu_ask_yes_no(opeu_scensel_ready_demo))
        goto start;
      goto restart;
    }
    opeu_delay_units(15);
    opeu_ui_text(opeu_scensel_ready_colors);
    opeu_confirm_generals();
    opeu_army_position(0x14, 0x170);
  } else if (selection == 2) {
    new_game = 0;
    opeu_ui_text(opeu_scensel_load_colors);
    if (!opeu_load_saved_game())
      goto restart;
    opeu_army_position(0x1c, 0xbc);
  } else
    goto title;
  opeu_staff_restore_bottom();
  opeu_text_attribute(4);
  opeu_ui_text(opeu_ui_framed_text(0x1c, 0xbc, opeu_scensel_ready_blank));
  opeu_army_position(0x1c, 0xbc);
  if (!opeu_ask_yes_no(opeu_scensel_ready))
    goto restart;
start:
  opeu_load_scenario_graphics();
  opeu_ui_text(opeu_scensel_done_colors);
  opeu_dos_close(handle);
  return new_game;
}
